metadata.prompt:
Classify the request into the prototype's supported intent and input modality. Choose exactly one intent and one modality. Use scanned_document for scanned PDFs or reports that require OCR, spreadsheet for workbook-style/tabular inputs, and image for photo-based visual analysis.

Request payload:
{
  "user_goal": "Read the inspection report , analyze and create an approval summary",
  "attachments": [
    {
      "name": "inspection_report.pdf",
      "media_type": "application/pdf",
      "description": null,
      "document_type": "pdf",
      "has_extractable_text": true,
      "page_count": 2
    }
  ],
  "event_context": {
    "session_id": "04d1df85-1d69-47a8-940c-36602f4f4d4f",
    "task_id": "ecfb4bef-942b-4e81-b63c-e3a9bc32f4f5",
    "user_id": "user-bob-0002"
  }
}

Return a JSON object that matches this schema exactly:
{
  "$defs": {
    "AgentIntent": {
      "description": "Supported high-level intents for the prototype Agent.",
      "enum": [
        "computation",
        "document_drafting",
        "multimodal_analysis"
      ],
      "title": "AgentIntent",
      "type": "string"
    },
    "InputModality": {
      "description": "Prototype input modalities the Agent can classify explicitly.",
      "enum": [
        "spreadsheet",
        "scanned_document",
        "image"
      ],
      "title": "InputModality",
      "type": "string"
    },
    "WorkflowName": {
      "description": "The three prototype workflows governed by the Execution Controller.",
      "enum": [
        "computation",
        "scanned_document_approval",
        "multimodal_analysis"
      ],
      "title": "WorkflowName",
      "type": "string"
    }
  },
  "additionalProperties": false,
  "description": "Structured Agent understanding suitable for Controller workflow selection.",
  "properties": {
    "intent": {
      "$ref": "#/$defs/AgentIntent"
    },
    "modality": {
      "$ref": "#/$defs/InputModality"
    },
    "summary": {
      "minLength": 1,
      "title": "Summary",
      "type": "string"
    },
    "workflow": {
      "$ref": "#/$defs/WorkflowName"
    }
  },
  "required": [
    "intent",
    "modality",
    "workflow",
    "summary"
  ],
  "title": "IntentAnalysisResult",
  "type": "object"
}

